#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
	// your code goes here
    const ll mod = 998244353;
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<vector<int>> w(n+1);
        for(int i=1;i<=n;i++){
            int no ;
            cin>>no;
            w[no].push_back(i);
        }
        vector<int> dp(n+2,0),nd(n+2,0);
        dp[0]=1;
        auto cntP = [&](int l,int r,int i){
            return min(l,i) +max(0,r-(n-i));
        };
        auto cntS = [&](int l,int r,int i){
            return min(r,n-i+1)+max(0,l-(i-1));
        };
        auto good =[&](int l,int r,int l2,int r2,int v){
            for(int i:w[v]){
                int m_p = (i+1)/2;
                int m_s = (n-i+2)/2;
                bool pre = cntP(l,r,i) < m_p && cntP(l2,r2,i) >=m_p;
                bool suf = cntS(l,r,i) < m_s  && cntS(l2,r2,i) >=m_s;
                if(!pre && !suf) return 0;
            }
            return 1;
        };
        for(int v=1;v<=n;v++){
            for(int l=0;l<=v;l++){
                nd[l] = 0;
            }
            for(int l=0;l<=v-1;l++){
                if(!dp[l]) continue;
                int r = v-1-l;
                if(good(l,r,l+1,r,v)){
                    nd[l+1] += dp[l];
                    if(nd[l+1] >= mod) nd[l+1] -=mod;
                }
                if(v<n && good(l,r,l,r+1,v)){
                    nd[l]+=dp[l];
                    if(nd[l]>=mod) nd[l] -=mod;
                }
            }
            swap(dp,nd);
        }
        ll ans = 0;
        for(int l=0;l<=n;l++){
            ans+=dp[l];
        }
        cout<<ans%mod<<"\n";
    }
}
